// Conservative broad phase only. Exact segment / circle / cell tests still run.
export function spatialIndex(items,bounds,yOf){const buckets=new Map(),queries=new Map(),size=8;for(const item of items){const b=bounds(item),y=Math.round(yOf(item)*100),loX=Math.floor((b.x-1e-7)/size),hiX=Math.floor((b.x+b.w+1e-7)/size),loZ=Math.floor((b.z-1e-7)/size),hiZ=Math.floor((b.z+b.d+1e-7)/size);for(let x=loX;x<=hiX;x++)for(let z=loZ;z<=hiZ;z++){const key=y+':'+x+':'+z;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(item);}}return{buckets,queries,size,heights:[...new Set(items.map(item=>Math.round(yOf(item)*100)))].sort((a,b)=>a-b)};}
export function querySpatial(index,x,z,y,r=0){const x0=Math.floor((x-r)/index.size),x1=Math.floor((x+r)/index.size),z0=Math.floor((z-r)/index.size),z1=Math.floor((z+r)/index.size),y0=Math.floor((y-.011)*100),y1=Math.ceil((y+.011)*100),key=[x0,x1,z0,z1,y0,y1].join(':');if(index.queries.has(key))return index.queries.get(key);const result=new Set();for(let iy=y0;iy<=y1;iy++)for(let ix=x0;ix<=x1;ix++)for(let iz=z0;iz<=z1;iz++)for(const item of index.buckets.get(iy+':'+ix+':'+iz)??[])result.add(item);const list=[...result];index.queries.set(key,list);if(index.queries.size>256)index.queries.delete(index.queries.keys().next().value);return list;}

// Range query for a cylinder's vertical extent; owner queries retain exact floor lookup.
export function querySpatialRange(index,x,z,minY,maxY,r=0){const x0=Math.floor((x-r)/index.size),x1=Math.floor((x+r)/index.size),z0=Math.floor((z-r)/index.size),z1=Math.floor((z+r)/index.size),ys=index.heights.filter(y=>y>=Math.floor(minY*100)-1&&y<=Math.ceil(maxY*100)+1),key='range:'+x0+':'+x1+':'+z0+':'+z1+':'+ys.join(',');if(index.queries.has(key))return index.queries.get(key);const found=new Set();for(const y of ys)for(let ix=x0;ix<=x1;ix++)for(let iz=z0;iz<=z1;iz++)for(const item of index.buckets.get(y+':'+ix+':'+iz)??[])found.add(item);const list=[...found];index.queries.set(key,list);if(index.queries.size>256)index.queries.delete(index.queries.keys().next().value);return list;}
